// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {
    AccessControlEnumerable
} from "@openzeppelin/contracts/access/extensions/AccessControlEnumerable.sol";
import { IPredictionMarket } from "../interfaces/IPredictionMarket.sol";
import { ITreasury } from "../interfaces/ITreasury.sol";
import { ISubAccount } from "../interfaces/ISubAccount.sol";
import { Roles } from "../access/Roles.sol";

/// @title PredictionMarket
/// @notice 链下撮合 + 链上确认:链上只接受撮合/结算服务提交的、已校验结果;同 orderId 幂等。
/// @dev **资金走真实 HSK,本合约自身不持币**:只记持仓、判胜负、授权资金动作。
///      - 买入:调 `ISubAccount.payToTreasury()`,子账户 → 金库(本合约需在**工厂**上持 MARKET_ROLE);
///      - 卖出/结算派付:调 `ITreasury.payout()`,金库 → 子账户(需在**金库**上持 MARKET_ROLE)。
///      两处授权缺一不可,且都只允许固定去向——本合约无法把钱转给任意地址。
///      链上无法枚举持仓,结算由结算服务在链下算好后成批驱动。
///      Points 不上链(链下记账),仓位不可转让(无 transfer,守 BR-15)。
contract PredictionMarket is IPredictionMarket, AccessControlEnumerable {
    enum EventStatus {
        None,
        Live,
        Closed,
        Settled,
        Invalid
    }

    struct MarketEvent {
        EventStatus status;
        uint8 resultType;
        /// @notice 获胜候选之一。**多档同时获胜时只记第一个**,仅供事件/浏览器展示。
        /// @dev 判定谁能拿钱**一律读 `isWinning`**,不读这个字段——
        ///      不互斥盘可以有多个赢家,单值字段表达不了。保留它是为了不破坏
        ///      `EventSettled` 事件的既有索引与外部读取。
        bytes32 winningOutcome;
        bytes32 finalValueHash;
        bytes32 evidenceHash;
    }

    /// @notice 唯一资金池(Market 以自身 MARKET_ROLE 调其 payout)
    ITreasury public immutable treasury;

    /// @notice 子账户工厂。**角色注册表在这里**——子账户校验调用方是否持 MARKET_ROLE 时读它,
    ///         故本合约必须在工厂上被授予 MARKET_ROLE 才能让子账户付款。
    address public immutable factory;

    mapping(uint256 => MarketEvent) private _events;

    /// @notice 单次批量入口最多几条（第二次审计 #5：过大的批次会因 gas 不够整笔失败,
    ///         且失败形态是 out-of-gas 回滚,重试永远是同一批、永远失败)。
    /// @dev 200 比后端现行分块(`PM_CHAIN_SUBMIT_BATCH_MAX=20`)大一个数量级,又远低于
    ///      任何一条链的区块 gas 上限。它不是"最优批量",是让**不可能提交无界批次**
    ///      这件事由合约保证,而不是由一个环境变量保证。
    uint256 public constant MAX_BATCH = 200;

    /// @notice 获胜候选集合:eventId => outcome => 是否获胜。
    ///
    /// @dev **一个事件可以有多个赢家**。「多元不互斥」盘口(NVDA ≥$180 / ≥$185 / ≥$190)
    ///      在收盘 $190 时三档同时成立,三档的持有人都该拿到钱。
    ///
    ///      原先只有单值 `winningOutcome`,`batchSettle` 用 `outcome != winningOutcome`
    ///      判输赢,于是第二个赢家会撞上 `loser must be paid zero` 被拒付——
    ///      不互斥盘只能拆成 N 个独立事件来绕开,而那让前后台的表现和互斥盘不一致。
    ///
    ///      两条安全护栏一条没动:输家仍必须拿零,派付仍不得超过持仓。
    mapping(uint256 => mapping(bytes32 => bool)) public isWinning;

    /// @notice orderId => 是否已处理(幂等)
    mapping(bytes32 => bool) public orderProcessed;

    /// @notice 仓位:subAccount => eventId => outcome => shares(不可转让,守 BR-15)
    /// @dev outcome 维度见 IPredictionMarket 注释(D3):PRD 仓位为「事件 × 候选项 × 方向」三维。
    mapping(address => mapping(uint256 => mapping(bytes32 => uint256))) public positions;

    /// @notice 结算幂等:eventId => subAccount => outcome => 是否已结算
    /// @dev 未命中(payout=0)也会置位并清仓,防止同一持仓被重复处理。
    mapping(uint256 => mapping(address => mapping(bytes32 => bool))) public settled;

    /// @notice 买入成交累计扣走的现金 HSK 成本(守恒 invariant 用):恒等 Ledger.totalDebited。
    /// @dev 只由买入 debit 增长。卖出/结算走 Ledger.payout(credit 侧),不经 debit,故不影响本值——
    ///      恒等式 totalDebited == totalCostLocked 与 credited ≡ Σ余额+debited+recycled 均无需重构。
    uint256 public totalCostLocked;

    /// @notice 每个事件实收的 HSK。成对成交时两条腿之和恒为 `shares`,销毁时按份退回。
    /// @dev 结算派付的硬上界。定价在链下,合约无从判断价格是否公允——
    ///      但「出池不得超过进池」不需要知道价格,而它足以让金库在这条路径上不受损。
    mapping(uint256 => uint256) public collected;

    /// @notice 每个事件已派付的 HSK。与 `collected` 一起构成守恒约束。
    mapping(uint256 => uint256) public paid;

    /// @notice 成对成交 / 转让 / 销毁的幂等键。
    mapping(bytes32 => bool) public matchProcessed;

    /// 互补腿登记：`complement[eventId][某一腿] = 另一腿`，双向写入。
    ///
    /// **成对成交与对冲销毁的两条腿都必须是「同一档的正反面」，不能是两个不同的档。**
    /// 原先只校验两条腿不相等，于是「>80 的是」可以和「>90 的否」撮到一起——
    /// 那是两个独立的档，收盘 85 时**两档同时成立**，两边都该拿 1 HSK/份，
    /// 而池里只有 1 份的钱，事件从此结算不了（2026-08-18 审计）。
    ///
    /// `confirmMerge` 同构：销毁会放走 1 HSK/份，两条腿若不是一对，
    /// 放走的是别人那一份的钱，两档各自的对手腿索赔一分没少（2026-08-19 审计追加）。
    ///
    /// outcome 键是链下算的不透明哈希，合约拆不开、判断不了两个键是不是同一档，
    /// 所以由建盘时显式登记。**加法式设计**：不改键编码，存量持仓不受影响。
    mapping(uint256 => mapping(bytes32 => bytes32)) public complement;

    /// @notice 已承诺但未兑付的总额 = Σ(collected − paid)。
    ///
    /// @dev 与 `金库余额 ≥ outstanding` 一起构成**同时适用于做市与不做市**的不变量：
    ///      - 用户对用户成交：进池与承诺同额增长,不占用储备;
    ///      - 房子做对手方：承诺涨得比进池多,差额占用金库自由储备,见底即拒绝开新仓。
    ///      做市的敞口上限因此不需要声明——它就是金库实际持有的钱。
    uint256 public outstanding;

    constructor(address admin, address treasury_, address factory_) {
        require(admin != address(0), "zero admin");
        require(treasury_ != address(0), "zero treasury");
        require(factory_ != address(0), "zero factory");
        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        // 顺带授事件管理权：admin 本就能自授任意角色，这里给上只是省一步，
        // 且保证冷钱包在应急时能直接开/关事件。
        _grantRole(Roles.EVENT_ADMIN_ROLE, admin);
        treasury = ITreasury(treasury_);
        factory = factory_;
    }

    /// @notice 运营入口:把事件置为 Live。
    /// @dev createEvent 的参数化校验与 invalidateEvent(独立无效流转)属运营后台(模块 9);
    ///      本合约提供 open/close 两个状态入口即可支撑撮合/结算全流程。
    ///      已结算事件不可复活:否则已公布结果的事件还能建新仓,且链上结果字段残留造成自证歧义。
    function openEvent(uint256 eventId) external onlyRole(Roles.EVENT_ADMIN_ROLE) {
        require(_events[eventId].status != EventStatus.Settled, "already settled");
        _events[eventId].status = EventStatus.Live;
        emit EventOpened(eventId);
    }

    /// @inheritdoc IPredictionMarket
    /// @dev 停止交易(数据区间结束/封盘):只能从 Live 关。已结算/无效不可关(终态)。
    ///      Closed 后 batchConfirm/confirmSell 因 Live 校验自动被挡。
    function closeEvent(uint256 eventId) external onlyRole(Roles.EVENT_ADMIN_ROLE) {
        require(_events[eventId].status == EventStatus.Live, "not live");
        _events[eventId].status = EventStatus.Closed;
        emit EventClosed(eventId);
    }

    function eventStatus(uint256 eventId) external view returns (uint8) {
        return uint8(_events[eventId].status);
    }

    // ─────────────────── 成对成交与事件级记账 ───────────────────
    //
    // 撮合在链下,合约无从判断价格是否公允。这一组的思路是不去判断价格,
    // 而是保证**进池等于出池**：两条腿的金额由合约算(`makerPays = shares - takerPays`),
    // 派付受 `collected` 约束。价格算错时钱在两个用户之间转移,池子分文不动。

    /// 增加承诺,并核对金库真的备得起。**所有让 `collected` 上涨的路径都要过这里。**
    function _commit(uint256 eventId, uint256 amount) private {
        collected[eventId] += amount;
        outstanding += amount;
        require(address(treasury).balance >= outstanding, "treasury cannot back this");
    }

    /// 释放承诺（派付、销毁、卖出）。
    function _release(uint256 eventId, uint256 amount) private {
        require(collected[eventId] >= amount, "release exceeds collected");
        collected[eventId] -= amount;
        outstanding -= amount;
    }

    /// @notice 成对建仓：taker 与 maker 各持一侧,两条腿之和恰为 `shares` HSK。
    /// @dev `makerPaysHSK` **不由调用方给**,合约自己算——这是价格错误无法伤到金库的原因。
    /// @notice 登记一档的互补腿（正反面）。建盘时按档调用，成对成交与对冲销毁据此校验。
    /// @dev 幂等：重复登记同一对无副作用；**已登记的不允许改**——改掉等于把
    ///      已成交的两条腿重新配对，历史成交的守恒依据就没了。
    function registerComplement(uint256 eventId, bytes32 sideA, bytes32 sideB)
        external
        onlyRole(Roles.EVENT_ADMIN_ROLE)
    {
        require(sideA != sideB, "same side");
        require(sideA != bytes32(0) && sideB != bytes32(0), "zero outcome");
        bytes32 exA = complement[eventId][sideA];
        bytes32 exB = complement[eventId][sideB];
        require(exA == bytes32(0) || exA == sideB, "A already paired");
        require(exB == bytes32(0) || exB == sideA, "B already paired");
        complement[eventId][sideA] = sideB;
        complement[eventId][sideB] = sideA;
        emit ComplementRegistered(eventId, sideA, sideB);
    }

    function confirmMatch(
        bytes32 matchId,
        address takerSub,
        address makerSub,
        uint256 eventId,
        bytes32 takerOutcome,
        bytes32 makerOutcome,
        uint256 shares,
        uint256 takerPaysHSK
    ) external onlyRole(Roles.MATCHER_ROLE) {
        require(!matchProcessed[matchId], "match processed");
        require(_events[eventId].status == EventStatus.Live, "event not live");
        require(shares > 0, "zero shares");
        require(takerOutcome != makerOutcome, "same side");
        // **两条腿必须是同一档的正反面**。只校验「不相等」的话，
        // 「>80 的是」能和「>90 的否」撮成一笔——两档可同时成立，
        // 于是两边都该拿钱而池里只有一份的钱，事件永久结算不了。
        require(complement[eventId][takerOutcome] == makerOutcome, "legs not complementary");
        require(takerPaysHSK <= shares, "cost exceeds shares");

        matchProcessed[matchId] = true;
        uint256 makerPaysHSK = shares - takerPaysHSK;

        if (takerPaysHSK > 0) ISubAccount(takerSub).payToTreasury(takerPaysHSK);
        if (makerPaysHSK > 0) ISubAccount(makerSub).payToTreasury(makerPaysHSK);

        totalCostLocked += shares;
        _commit(eventId, shares);
        positions[takerSub][eventId][takerOutcome] += shares;
        positions[makerSub][eventId][makerOutcome] += shares;

        emit MatchConfirmed(
            matchId, takerSub, makerSub, eventId, takerOutcome, makerOutcome, shares, takerPaysHSK
        );
    }

    /// @notice 转让：仓位从卖方到买方,钱反向。**池子不动**,故 `collected` 不变。
    function confirmTransfer(
        bytes32 matchId,
        address fromSub,
        address toSub,
        uint256 eventId,
        bytes32 outcome,
        uint256 shares,
        uint256 priceHSK
    ) external onlyRole(Roles.MATCHER_ROLE) {
        require(!matchProcessed[matchId], "match processed");
        require(_events[eventId].status == EventStatus.Live, "event not live");
        require(shares > 0, "zero shares");
        require(priceHSK <= shares, "cost exceeds shares");
        require(positions[fromSub][eventId][outcome] >= shares, "insufficient shares");

        matchProcessed[matchId] = true;
        positions[fromSub][eventId][outcome] -= shares;
        positions[toSub][eventId][outcome] += shares;

        // 买方的钱经金库转给卖方。两笔金额相同,池子净变化为零
        if (priceHSK > 0) {
            ISubAccount(toSub).payToTreasury(priceHSK);
            treasury.payout(fromSub, priceHSK, "TRANSFER", keccak256(abi.encode("XFER", matchId)));
        }
        emit PositionTransferred(matchId, fromSub, toSub, eventId, outcome, shares, priceHSK);
    }

    /// @notice 对冲销毁：两侧同时退出,按 1 HSK/份退回并从实收中扣除。
    /// @dev 两人分得的钱之和必须等于 `shares`,否则又造出凭空的钱。
    function confirmMerge(
        bytes32 matchId,
        address subA,
        address subB,
        uint256 eventId,
        bytes32 outcomeA,
        bytes32 outcomeB,
        uint256 shares,
        uint256 aGetsHSK
    ) external onlyRole(Roles.MATCHER_ROLE) {
        require(!matchProcessed[matchId], "match processed");
        require(_events[eventId].status == EventStatus.Live, "event not live");
        require(shares > 0, "zero shares");
        require(outcomeA != outcomeB, "same side");
        // **销毁的两条腿同样必须是同一档的正反面**（与 `confirmMatch` 同一条口径）。
        // 销毁会 `_release` 掉 1 HSK/份并付给两人；两条腿若不是一对，
        // 放走的就是别人那一份的钱——两档各自的对手腿还在，索赔一分没少，
        // 事件从此结算不了。校验放在改余额之前。
        require(complement[eventId][outcomeA] == outcomeB, "legs not complementary");
        require(aGetsHSK <= shares, "split exceeds shares");
        require(positions[subA][eventId][outcomeA] >= shares, "insufficient shares");
        require(positions[subB][eventId][outcomeB] >= shares, "insufficient shares");

        matchProcessed[matchId] = true;
        positions[subA][eventId][outcomeA] -= shares;
        positions[subB][eventId][outcomeB] -= shares;
        _release(eventId, shares);
        totalCostLocked -= shares;

        uint256 bGetsHSK = shares - aGetsHSK;
        if (aGetsHSK > 0) {
            treasury.payout(subA, aGetsHSK, "MERGE", keccak256(abi.encode("MRGA", matchId)));
        }
        if (bGetsHSK > 0) {
            treasury.payout(subB, bGetsHSK, "MERGE", keccak256(abi.encode("MRGB", matchId)));
        }
        emit PositionsMerged(matchId, subA, subB, eventId, shares, aGetsHSK);
    }

    // `confirmSell`（卖回池子）已移除（2026-08-19 审计）：
    //
    // 它与已删的三个单边入口同构——无对手方、金库直接出钱，护栏只有
    // `proceedsHSK <= shares` 与 `_release` 的 `collected >= proceeds`，
    // 最坏情况是持 MATCHER_ROLE 的热钥匙把一批无价值份额按 1 HSK/份卖回，
    // 掏空**该事件**的整个池子。
    //
    // 既然确定不做市，卖出必须有真实买家接盘：改走 `confirmTransfer`
    // ——仓位从卖方到买方、钱反向、池子净变化为零。
    //
    // 代价是「按参考价随时卖出」不再成立（PRD BR-20 需同步修订）：
    // 无人接盘时卖单挂在簿上，不会成交。

    /// @inheritdoc IPredictionMarket
    /// @dev 证据非空校验 + 一次性状态守卫 + 结果落账 + 增强 event。逐持仓结算由 `batchSettle`
    ///      承担(链上无法枚举持仓,结算服务在链下算好每仓回款后成批提交)。
    function settleEvent(
        uint256 eventId,
        uint8 resultType,
        bytes32[] calldata winningOutcomes,
        bytes32 finalValueHash,
        bytes32 evidenceHash
    ) external onlyRole(Roles.SETTLER_ROLE) {
        require(evidenceHash != bytes32(0), "no evidence"); // BR-24
        MarketEvent storage e = _events[eventId];
        // 结算是一次性操作:重复结算会产生多条互相冲突的 EventSettled,
        // 破坏「结算判定纯链上自证」,并在结算落地后变成重复结算路径。
        require(e.status != EventStatus.Settled, "already settled");
        e.status = EventStatus.Settled;
        e.resultType = resultType;
        e.finalValueHash = finalValueHash;
        e.evidenceHash = evidenceHash;

        // **空集合是合法的**:不互斥盘可以一档都没成立(「≥$180/≥$185/≥$190」而收盘 $170),
        // 那时人人拿零。强行要求至少一个赢家会逼结算服务编一个出来。
        for (uint256 i = 0; i < winningOutcomes.length; i++) {
            isWinning[eventId][winningOutcomes[i]] = true;
        }
        // 单值字段只留给事件与外部读取;判定谁能拿钱一律读 `isWinning`
        e.winningOutcome = winningOutcomes.length > 0 ? winningOutcomes[0] : bytes32(0);

        emit EventSettled(eventId, resultType, e.winningOutcome, finalValueHash, evidenceHash);
        emit EventWinners(eventId, winningOutcomes);
        // 逐持仓结算见 batchSettle:链上无法枚举持仓,结果先在此落定,结算由结算服务成批驱动。
    }

    /// @inheritdoc IPredictionMarket
    /// @dev 逐持仓结算。事件须已 Settled;每个持仓幂等一次。命中回款 payout>0(Ledger.payout),
    ///      未命中传 0——仍清仓 + 置位 + 留 SettlementPaid,使「谁已结算、拿了多少」纯链上可查。
    ///      Points 不上链(链下记账,Q4)。整批原子:任一笔失败 revert 整批,重试需剔除已成功项。
    function batchSettle(
        uint256 eventId,
        address[] calldata subAccount,
        bytes32[] calldata outcome,
        uint256[] calldata payoutHSK
    ) external onlyRole(Roles.SETTLER_ROLE) {
        require(
            subAccount.length == outcome.length && outcome.length == payoutHSK.length,
            "length mismatch"
        );
        require(subAccount.length <= MAX_BATCH, "batch too large");
        MarketEvent storage ev = _events[eventId];
        require(ev.status == EventStatus.Settled, "not settled");
        for (uint256 i = 0; i < subAccount.length; i++) {
            require(!settled[eventId][subAccount[i]][outcome[i]], "position settled");

            // **派付金额必须由持仓约束**。原实现 `payoutHSK` 完全由调用方指定、
            // `subAccount` 也不校验身份,于是持 SETTLER_ROLE 的热钥匙可以
            // 「开事件 → 结算 → 按金库全额派付给自己」直接清库。
            //
            // 每份获胜份额兑 1 HSK,链上份额与金额同为 18 位精度,故合法上限恰为持仓数。
            // 作废(resultType=1)退的是成本,成本必然小于份额×1 HSK(价格 1–99¢),
            // 所以同一个上限对两种结算都成立。
            uint256 held = positions[subAccount[i]][eventId][outcome[i]];
            // **读获胜集合而不是单值字段**:一个事件可以有多个赢家。
            // 护栏本身没变——没在获胜集合里的仍然必须拿零。
            if (ev.resultType == 0 && !isWinning[eventId][outcome[i]]) {
                require(payoutHSK[i] == 0, "loser must be paid zero");
            }
            require(payoutHSK[i] <= held, "payout exceeds position");
            // 事件级守恒：出池不得超过进池。定价在链下,合约判断不了价格是否公允,
            // 但这条不需要知道价格——撮合出任何差错,金库在本事件上的净支出都不为正
            paid[eventId] += payoutHSK[i];
            require(paid[eventId] <= collected[eventId], "payout exceeds collected");
            outstanding -= payoutHSK[i];

            settled[eventId][subAccount[i]][outcome[i]] = true;
            positions[subAccount[i]][eventId][outcome[i]] = 0;
            if (payoutHSK[i] > 0) {
                treasury.payout(
                    subAccount[i],
                    payoutHSK[i],
                    "SETTLE",
                    keccak256(abi.encode("SETTLE", eventId, subAccount[i], outcome[i]))
                );
