/// @title Roles
/// @notice 全系统统一角色常量。资金变动权限收敛到服务角色,用户 EOA 无资金支配权。
library Roles {
    bytes32 internal constant ACTIVITY_SERVICE_ROLE = keccak256("ACTIVITY_SERVICE_ROLE");
    bytes32 internal constant MATCHER_ROLE = keccak256("MATCHER_ROLE");
    bytes32 internal constant SETTLER_ROLE = keccak256("SETTLER_ROLE");
    /// @notice 应急停机。持有者只能调 `Treasury.pause()`,**解冻要 DEFAULT_ADMIN(多签)**。
    ///         不对称是它敢做成热钥匙、单签、秒级的全部理由:泄露了最坏只是拒绝服务。
    bytes32 internal constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    /// @notice 资金动作的专用角色,**由 Market 合约持有**(在工厂与金库两处):
    ///         工厂上的用于让子账户付款(下注),金库上的用于派付(卖出/结算)。
    ///         撮合服务→Market→资金 单向,运营地址不得直接持有。
    bytes32 internal constant MARKET_ROLE = keccak256("MARKET_ROLE");

    /// @notice 开/关事件。**从 DEFAULT_ADMIN 拆出来的最小权限**:
    ///         后端热钱包只需要开关事件,不该顺带拿到「能给自己授任何角色」的超级权限——
    ///         热钥匙一旦泄露,攻击者可自授 MARKET_ROLE 等,任何削权都会被绕过。
    bytes32 internal constant EVENT_ADMIN_ROLE = keccak256("EVENT_ADMIN_ROLE");
}

