pragma solidity ^0.8.24;

/// @title IPredictionMarket
/// @notice 预测市场接口:链下撮合 + 链上确认。
/// @dev event 是自助验证的链上真相源,字段本期定全(链上 event 只加不改)。
///      `outcome` 维度(D3):PRD 的仓位是「事件 × 候选项 × yes/no 方向」三维,
///      链上必须带该维度,否则用户能读到 EventSettled 的胜出结果、却读不到自己押的哪一边,
///      「结算判定纯链上自证」在结构上就不成立。编码由链下约定
///      (建议 keccak256(abi.encode(outcomeId, direction))),本期仅透传与建仓,不做语义解释。
///      `EventSettled` 带结算结果(类型/胜出方向/最终值哈希),使判定可纯链上自证;
///      `evidenceHash` 承诺证据不可篡改。
interface IPredictionMarket {
    /// @notice 成对建仓。两条腿之和恒为 `shares` HSK,故进池等于将来的出池。
    /// 一档的互补腿（正反面）已登记。成对成交据此校验两条腿配不配。
    event ComplementRegistered(uint256 indexed eventId, bytes32 sideA, bytes32 sideB);

    /// 事件结清：没派出去的承诺已释放，`collected` 收敛到 `paid`。
    event EventFinalized(uint256 indexed eventId, uint256 released);

    event MatchConfirmed(
        bytes32 indexed matchId,
        address indexed takerSub,
        address indexed makerSub,
        uint256 eventId,
        bytes32 takerOutcome,
        bytes32 makerOutcome,
        uint256 shares,
        uint256 takerPaysHSK
    );

    /// @notice 仓位转让。池子不动。
    event PositionTransferred(
        bytes32 indexed matchId,
        address indexed fromSub,
        address indexed toSub,
        uint256 eventId,
        bytes32 outcome,
        uint256 shares,
        uint256 priceHSK
    );

    /// @notice 对冲销毁。两侧同时退出,按 1 HSK/份退回。
    event PositionsMerged(
        bytes32 indexed matchId,
        address indexed subA,
        address indexed subB,
        uint256 eventId,
        uint256 shares,
        uint256 aGetsHSK
    );

    event EventSettled(
        uint256 indexed eventId,
        uint8 resultType,
        bytes32 winningOutcome,
        bytes32 finalValueHash,
        bytes32 evidenceHash
    );
    /// @notice 完整的获胜候选集合。`EventSettled.winningOutcome` 只带第一个,
    ///         多档同时获胜时看这条才知道全部赢家。
    event EventWinners(uint256 indexed eventId, bytes32[] winningOutcomes);
    event EventOpened(uint256 indexed eventId);
    event EventClosed(uint256 indexed eventId);
    /// @notice 结算一笔(逐持仓)。`payoutHSK` 为该持仓的回款(未命中为 0),供纯链上自证。
    event SettlementPaid(
        uint256 indexed eventId, address indexed subAccount, bytes32 outcome, uint256 payoutHSK
    );

    // `confirmPrediction` / `batchConfirm` 已移除（2026-08-18 审计）：
    // 单边成交只记用户付的钱、却给份额数的持仓，赢家结算时 `paid > collected`，
    // 而 `batchSettle` 原子，一个这样的持仓连坐整批。建仓只剩 `confirmMatch` 一条路。

    function settleEvent(
        uint256 eventId,
        uint8 resultType,
        bytes32[] calldata winningOutcomes,
        bytes32 finalValueHash,
        bytes32 evidenceHash
    ) external;

    /// @notice 逐持仓结算。链上无法枚举持仓,由结算服务在链下算好每个持仓的回款后成批提交。
    ///         每个 (eventId, subAccount, outcome) 幂等一次;命中回款 > 0、未命中传 0(仅清仓 + 留痕)。
    function batchSettle(
        uint256 eventId,
        address[] calldata subAccount,
        bytes32[] calldata outcome,
        uint256[] calldata payoutHSK
    ) external;

    /// @notice 关闭交易(Live → Closed):停止新的成交确认,已结算/无效事件不可关闭。
    function closeEvent(uint256 eventId) external;
}

