/// @title ITreasury
/// @notice 唯一资金池:空投发出、派付发出、下注与回收收入。
/// @dev Market 只用得到 `payout`——它不持币、也不发空投,只在胜负判定后授权金库付款。
interface ITreasury {
    function payout(address subAccount, uint256 amount, bytes32 reason, bytes32 idemKey) external;
}
